import { PropertyGrid, Card } from "march/ui"

// emoji avatar yapıcı: soldaki avatar, sağdaki ızgaranın değerleriyle çizilir (bind:value)
const ROWS = [
  { key: "face", label: "Yüz", type: "segmented" as const, options: ["😀", "😎", "🤖", "🦊"], group: "Avatar" },
  { key: "size", label: "Boyut", type: "slider" as const, min: 32, max: 96, unit: "px", group: "Avatar" },
  { key: "round", label: "Yuvarlak", type: "switch" as const, group: "Çerçeve" },
  { key: "ring", label: "Halka rengi", type: "color" as const, group: "Çerçeve" },
]

export function AvatarMaker() {
  let $look: Record<string, unknown> = { face: "🦊", size: 64, round: true, ring: "#f2801f" }
  return <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "center"] }} style={{
        width: `${Number($look.size) + 24}px`, height: `${Number($look.size) + 24}px`, fontSize: `${Number($look.size) * 0.6}px`,
        borderRadius: $look.round ? "50%" : "12px", border: `4px solid ${String($look.ring)}`,
      }}>{String($look.face)}</div>
    </Card>
    <PropertyGrid properties={ROWS} bind:value={$look} label="Avatar" search={false} footer={false} history={false} dirty={false} />
  </div>
}

import { PropertyGrid, toast } from "march/ui"

// gerçek hayattan: bildirim ayarları. Gruplar, arama, değişiklik işaretleri; Kaydet sunucuya gönderir (burada bir bildirim),
// sessiz saatlerin bitişi başlangıcından önce olamaz
const ROWS = [
  { key: "email", label: "E-posta bildirimleri", type: "switch" as const, group: "E-posta" },
  { key: "digest", label: "Özet sıklığı", type: "select" as const, options: [{ value: "daily", label: "Günlük" }, { value: "weekly", label: "Haftalık" }, { value: "never", label: "Hiç" }], group: "E-posta", hidden: (v: Record<string, unknown>) => !v.email },
  { key: "push", label: "Anlık bildirimler", type: "switch" as const, group: "Mobil" },
  { key: "quietFrom", label: "Sessiz saat başlangıcı", type: "int" as const, min: 0, max: 23, unit: "sa", group: "Mobil" },
  { key: "quietTo", label: "Sessiz saat bitişi", type: "int" as const, min: 0, max: 23, unit: "sa", group: "Mobil",
    validate: (to: unknown, v: Record<string, unknown>) => (Number(to) <= Number(v.quietFrom) ? "Bitiş başlangıçtan sonra olmalı" : null) },
]

export function NotificationSettings() {
  let $prefs: Record<string, unknown> = { email: true, digest: "weekly", push: true, quietFrom: 22, quietTo: 7 }
  return <PropertyGrid properties={ROWS} bind:value={$prefs} label="Bildirim ayarları"
    onSave={(v) => toast(`Kaydedildi: özet ${String(v.digest)}`, { kind: "success" })} />
}

import { PropertyGrid, Toolbar, Button, type PropertyGridApi } from "march/ui"

// PropertyGrid'in bütün özellikleri: satırlar (kendi denetimi, açıklama, anahtar kelime, ad, yer tutucu, adım, birim,
// salt okunur, gizli, doğrulama), value + setValue + onChange, saved, onSave, ad, history (burada ızgaranın kendi küçük
// yığını: uygulamanın geri alma kaydına yazmaz), dirty (false: "kaydedilmedi" kaydına yazmaz), id, grup sırası, arama, yerleşim, api, başlık / satır /
// alt çubuk düğmeleri, değişiklik işaretleri, grup araçları, açık grupların saklanması, başta açık gruplar, metinler, sınıf.
const Faces = (p: { value?: unknown; setValue?: (v: unknown) => void }) => <div role="group" sx={{ flex: "row", gap: 1 }}>
  {["🙂", "🚀", "🌙"].map((e) => <Button size="sm" variant="ghost" pressed={p.value === e} on:click={() => p.setValue?.(e)}>{e}</Button>)}
</div>

const ROWS = [
  { key: "name", label: "Ad", group: "Kimlik", placeholder: "Proje adı", keywords: "başlık isim", name: "project-name", description: "Listelerde görünür" },
  { key: "icon", label: "Simge", group: "Kimlik", control: Faces },
  { key: "id", label: "Kimlik", group: "Kimlik", readonly: true },
  { key: "budget", label: "Bütçe", type: "number" as const, unit: "₺", step: 500, min: 0, group: "Plan", validate: (v: unknown) => (Number(v) > 10000 ? "En çok 10 000 ₺" : null) },
  { key: "public", label: "Herkese açık", type: "switch" as const, group: "Plan" },
  { key: "link", label: "Paylaşım bağlantısı", group: "Plan", hidden: (v: Record<string, unknown>) => !v.public },
]

// history: yalnız bu ızgaranın geri alma yığını (push, undo / redo, adım adları); başlıktaki Geri al / Yinele onu kullanır
type Step = { label: string; undo: () => void; redo: () => void }
function ownHistory() {
  let $past: Step[] = []
  let $future: Step[] = []
  return {
    push: (s: Step) => { $past = [s, ...$past]; $future = [] },
    undo: () => { const [s, ...rest] = $past; if (s) { s.undo(); $past = rest; $future = [s, ...$future] } },
    redo: () => { const [s, ...rest] = $future; if (s) { s.redo(); $future = rest; $past = [s, ...$past] } },
    canUndo: () => $past.length > 0, canRedo: () => $future.length > 0,
    past: () => $past.map((s) => s.label), future: () => $future.map((s) => s.label),
    markSaved: () => {},
  }
}

export function PropertyGridLab() {
  let $value: Record<string, unknown> = { name: "Mars", icon: "🚀", id: "p-42", budget: 4000, public: false, link: "marchjs.com/p/42" }
  let $saved: Record<string, unknown> = { ...$value }
  let $edits = 0
  let grid: PropertyGridApi | undefined
  return <div sx={{ flex: "col", gap: 2 }}>
    <Toolbar label="Lab düğmeleri">
      <Button size="sm" variant="secondary" on:click={() => grid?.revert()}>Geri dön (api)</Button>
      <Button size="sm" variant="secondary" on:click={() => grid?.focus("budget")}>Bütçeye git</Button>
      <span sx={{ text: "sm" }}>düzenleme: {$edits} · kayıtlı ad: {String($saved.name)}</span>
    </Toolbar>
    <PropertyGrid
      properties={ROWS}
      value={$value}
      setValue={(v) => $value = v}
      onChange={() => $edits++}
      saved={$saved}
      onSave={(v) => { $saved = { ...v } }}
      label="Proje ayarları"
      history={ownHistory() as never}
      dirty={false}
      id="lab-project"
      groups={["Plan", "Kimlik"]}
      search
      layout="auto"
      api={(a) => grid = a}
      historyButtons
      resetButtons
      changeMarks
      footer
      groupTools
      persist="lab-pg"
      openGroups={["Plan", "Kimlik"]}
      labels={{ search: "Ayar ara", save: "Kaydet", revert: "Vazgeç", noChanges: "Değişiklik yok", unsaved: (n) => `${n} kaydedilmemiş`, changed: "değişti", empty: "Satır yok", noMatch: (q) => `"${q}" bulunamadı`, openAll: "Hepsini aç", closeAll: "Hepsini kapat" }}
      class="lab-pg"
    />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PropertyGridLab } from "./PropertyGridLab.tsx"

// PropertyGridLab'in testleri: gruplar, gizli satır, doğrulama, kaydet, kendi denetim
test("grup sırası Plan önce; gizli satır kapalıyken görünmez", () => {
  const s = renderTest(() => <PropertyGridLab />)
  const text = s.get(".lab-pg")?.textContent ?? ""
  expect(text.indexOf("Plan")).toBeGreaterThan(-1)
  expect(text.indexOf("Plan") < text.indexOf("Kimlik")).toBe(true)
  expect(s.sees("Paylaşım bağlantısı")).toBe(false)
  expect(s.sees("Değişiklik yok")).toBe(true)
})

test("kendi denetimi: simgeye basınca değer değişir, alt çubuk sayar", async () => {
  const s = renderTest(() => <PropertyGridLab />)
  await s.click("🌙")
  expect(s.sees("düzenleme: 1")).toBe(true)
  expect(s.sees("1 kaydedilmemiş")).toBe(true)
})

test("Kaydet onSave'i çalıştırır, kayıtlı değerler güncellenir", async () => {
  const s = renderTest(() => <PropertyGridLab />)
  await s.type("Ad", "Venüs")
  await s.click("Kaydet")
  await s.wait(() => s.sees("kayıtlı ad: Venüs"))
  expect(s.sees("kayıtlı ad: Venüs")).toBe(true)
  expect(s.sees("Değişiklik yok")).toBe(true)
})

test("doğrulama: bütçe sınırı aşılınca hata yazar", async () => {
  const s = renderTest(() => <PropertyGridLab />)
  await s.type("Bütçe", "20000")
  await s.wait(() => s.sees("En çok 10 000 ₺"))
  expect(s.sees("En çok 10 000 ₺")).toBe(true)
})

test("history: kendi yığını; başlıktaki Geri al son değişikliği geri alır", async () => {
  const s = renderTest(() => <PropertyGridLab />)
  await s.click("🌙")
  expect(s.sees("1 kaydedilmemiş")).toBe(true)
  await s.click(".m-pg-history button")
  await s.wait(() => s.sees("Değişiklik yok"))
  expect(s.sees("Değişiklik yok")).toBe(true)
})
